#include <bits/stdc++.h>

using namespace std;

using i64 = long long;

const i64 MOD = 1000000007LL;

struct F {
  i64 v;
  F(i64 x = 0) : v(x % MOD) {
    if (v < 0) v += MOD;
    if (v >= MOD) { cerr << "F error\n"; exit(1); }
  }
  F operator+(const F& o) const { return F((v + o.v) % MOD); }
  F operator-(const F& o) const { return F((v - o.v + MOD) % MOD); }
  F operator*(const F& o) const { return F((v * o.v) % MOD); }
  F operator/(const F& o) const { return (*this) * o.inv(); }
  F& operator+=(const F& o) { v = (v + o.v) % MOD; return *this; }
  F& operator-=(const F& o) { v = (v - o.v + MOD) % MOD; return *this; }
  F& operator*=(const F& o) { v = (v * o.v) % MOD; return *this; }
  F& operator/=(const F& o) { return (*this) *= o.inv(); }
  F inv() const {
    i64 e = MOD - 2, b = v, r = 1;
    while (e) {
      if (e & 1) r = (r * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1;
    }
    return F(r);
  }
};

template<typename T>
vector<vector<T>> mul(const vector<vector<T>>& A, const vector<vector<T>>& B) {
  int n = A.size(), m = A[0].size(), p = B[0].size();
  if (B.size() != m) { cerr << "mul dim error\n"; exit(1); }
  vector<vector<T>> C(n, vector<T>(p));
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < p; ++j)
      for (int k = 0; k < m; ++k)
        C[i][j] = C[i][j] + A[i][k] * B[k][j];
  return C;
}

template<typename T>
vector<T> mul(const vector<vector<T>>& A, const vector<T>& x) {
  int n = A.size(), m = A[0].size();
  if (x.size() != m) { cerr << "mat-vec dim error\n"; exit(1); }
  vector<T> y(n);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      y[i] = y[i] + A[i][j] * x[j];
  return y;
}

template<typename T>
vector<vector<T>> mat2D(int r, int c, const T& val = T()) {
  return vector<vector<T>>(r, vector<T>(c, val));
}

template<typename T>
vector<vector<vector<T>>> mat3D(int a, int b, int c, const T& val = T()) {
  return vector<vector<vector<T>>>(a, vector<vector<T>>(b, vector<T>(c, val)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  i64 n;
  int d;
  cin >> n >> d;

  auto S = mat3D<F>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k)
    for (int i = 0; i < d; ++i)
      S[k][i][(i + k) % d] = F(1);
  for (int k = 0; k < d; ++k)
    S[k][d][d] = F(1);

  auto U = mat3D<F>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d + 1; ++i)
      U[k][i][i] = F(1);
    for (int i = 0; i < d + 1; ++i)
      U[k][k][i] = F(1);
  }

  auto I = mat2D<F>(d + 1, d + 1);
  for (int i = 0; i < d + 1; ++i)
    I[i][i] = F(1);

  unordered_map<i64, vector<vector<F>>> dp;

  function<vector<vector<F>>(i64)> solve = [&](i64 p) -> vector<vector<F>> {
    if (dp.count(p)) return dp[p];
    if (p <= d) {
      auto M = I;
      for (int k = 0; k < p; ++k)
        M = mul(U[k], M);
      return M;
    }
    i64 block = d;
    while ((p + block - 1) / block > d) block *= d;
    auto child = solve(block);
    auto M = child;
    i64 rem = p - block;
    for (int k = 1; k < d; ++k) {
      if (rem >= block) {
        M = mul(mul(mul(S[d - k], child), S[k]), M);
        rem -= block;
      } else if (rem > 0) {
        M = mul(mul(mul(S[d - k], solve(rem)), S[k]), M);
        rem = 0;
      } else break;
    }
    return dp[p] = M;
  };

  auto M = solve(n);
  vector<F> base(d + 1);
  base[d] = F(1);
  auto ansVec = mul(M, base);
  F sum;
  for (auto& x : ansVec) sum += x;
  cout << sum.v << '\n';
}
